use proc_macro2::TokenStream;
use quote::quote;

pub fn expand(_input: TokenStream) -> syn::Result<TokenStream> {
    Ok(quote! {
        ::uniffi::setup_scaffolding!();

        #[no_mangle]
        pub unsafe extern "C" fn proffi_buf_free(ptr: *mut u8, len: usize, cap: usize) {
            if ptr.is_null() || cap == 0 { return; }
            // SAFETY: ptr/len/cap must be the exact triple emitted by a proffi_*
            // wrapper from the same cdylib. JS callers are required to round-trip
            // the buffer back unchanged.
            drop(::std::vec::Vec::from_raw_parts(ptr, len, cap));
        }
    })
}

