import proffi.greeter.Client
import greeter.HelloRequest
import greeter.ByeRequest

fun main() {
    val c = Client()
    val hello = c.greeter.sayHello(HelloRequest.newBuilder().setName("proffi").build())
    require(hello.message == "hello, proffi") { "got ${hello.message}" }
    val bye = c.greeter.sayBye(ByeRequest.newBuilder().setName("proffi").build())
    require(bye.message == "bye, proffi") { "got ${bye.message}" }
    println("OK")
}

fn main() -> std::io::Result<()> {
    println!("cargo:rerun-if-changed=../../proto/proffi.proto");
    prost_build::Config::new()
        .compile_protos(&["../../proto/proffi.proto"], &["../../proto"])?;
    Ok(())
}

fn main() {
    proffi_build::compile(&["proto/greeter.proto"], &["proto"]).unwrap();
}

//! proffi: Protobuf-defined FFI on top of UniFFI.
//!
//! Consumers must depend on both `proffi` and `uniffi` (the rpc/setup macros
//! emit absolute `::uniffi::...` paths that resolve against your crate's
//! extern prelude — re-exporting through `proffi` is not enough).
//!
//! ```ignore
//! // Cargo.toml:
//! //   proffi = "0.1"
//! //   uniffi = "0.29"
//!
//! use proffi::{rpc, Error};
//! proffi::setup!();
//!
//! #[rpc(service = "x.Y", method = "Z")]
//! fn handler(req: MyRequest) -> Result<MyResponse, Error> { /* ... */ }
//! ```

pub use proffi_macros::{rpc, setup};
pub use proffi_runtime::{Error, FfiResult, Payload};
pub use proffi_runtime as runtime;

//! proffi-runtime: byte envelope and generic runner for proffi.

mod error;
mod runner;

pub use error::Error;
pub use runner::run;

/// Generated `FfiResult`/`Error` types from `proto/proffi.proto`.
///
/// This module is intentionally `pub`: callers (the `proffi` facade, generated
/// client SDKs, and tests) need the wire types to construct or decode
/// envelopes. The wire format is part of proffi's public API surface.
pub mod proto {
    include!(concat!(env!("OUT_DIR"), "/proffi.rs"));
}

pub use proto::{FfiResult, ffi_result::Payload};

proffi::setup!();

mod proto { include!(concat!(env!("OUT_DIR"), "/greeter.rs")); }

#[proffi::rpc(service = "greeter.Greeter", method = "SayHello")]
fn say_hello(req: proto::HelloRequest) -> Result<proto::HelloResponse, proffi::Error> {
    Ok(proto::HelloResponse { message: format!("hello, {}", req.name) })
}

#[proffi::rpc(service = "greeter.Greeter", method = "SayBye")]
fn say_bye(req: proto::ByeRequest) -> Result<proto::ByeResponse, proffi::Error> {
    Ok(proto::ByeResponse { message: format!("bye, {}", req.name) })
}
